import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.DiAOIirN.js";import"./chunks/assets.00tzVH5c.js";var i=JSON.parse(`{"title":"AWS Elasticache","description":"","frontmatter":{},"headers":[],"relativePath":"guide/redis-tm-hosting/aws-elasticache.md","filePath":"guide/redis-tm-hosting/aws-elasticache.md","lastUpdated":1742529486000}`),a={name:`guide/redis-tm-hosting/aws-elasticache.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="aws-elasticache" tabindex="-1">AWS Elasticache <a class="header-anchor" href="#aws-elasticache" aria-label="Permalink to “AWS Elasticache”">​</a></h1><p>Elasticache is a managed caching service offered by Amazon Web Services (AWS), and it can be a good option when using BullMQ within the AWS infrastructure.</p><p>Here are some points to consider when using Elasticache with BullMQ within AWS:</p><ol><li>Use the standard cache-nodes setup (i.e. not the serverless version, as serverless for the moment uses an incompatible maxmemory-policy)</li><li>In order to access your Elasticache instance you will need to create a security group that allows the instance to be accessible to the services running BullMQ instances. </li><li></li></ol><figure><img src="/assets/image.DVDlotnh.png" alt=""><figcaption></figcaption></figure> 4. You will need to specify a VPC and an Inbound rule. Most likely just a custom TCP with port range 6379 and some suitable source (anywhere works well for testing and in some simpler cases), remember that the cluster will not be accessible outside from AWS in any case. 5. Attach the security group to your Elasticache cluster and to the services that need to access it. 6. Make sure that you are using maxmemory-policy: noeviction in your Redis parameters. As you cannot modify any default parameter group you will need to create a new one. <pre><code>1. Go to Elasticache &gt; Parameter Groups and click on Create.
2. Fill name, description, and Family, at the time of writing redis7 is the newest and the recommended one.

&lt;figure&gt;&lt;img src=&quot;../../.gitbook/assets/image (1).png&quot; alt=&quot;&quot;&gt;&lt;figcaption&gt;&lt;/figcaption&gt;&lt;/figure&gt;
</code></pre><ol start="7"><li>Click on &quot;Create&quot;. Then find the parameter group in the list. Click on Edit parameter values and then search for maxmemory-policy:</li></ol><figure><img src="/assets/image%20(1)%20(1).CbK1yiV2.png" alt=""><figcaption></figcaption></figure><ol start="8"><li>Change the value to &quot;noeviction&quot;:</li></ol><figure><img src="/assets/image%20(2).CjglkbiL.png" alt=""><figcaption></figcaption></figure><ol start="9"><li>Save changes. Now you can go to your elasticache cluster and change the parameter group to your custom group. Just find your instance, click on modify and go to cluster settings where you can change the parameter group:</li></ol><figure><img src="/assets/image%20(3).CtbDlTn-.png" alt=""><figcaption></figcaption></figure><ol start="10"><li>Preview changes and Modify. After this your cluster is ready to be used with BullMQ.</li></ol>`,14)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};